    "desc": "Подбрасывая инкрустированные камнями палочки, драконьи кости, раскладывая карты или используя другие инструменты для ворожбы, вы получаете знамение от иномировой сущности о результатах определённых действий, которые вы планируете совершить в течение следующих 30 минут. Мастер выбирает одно из следующих возможных знамений:\nБлаго, для хороших результатов\nГоре, для плохих результатов\nБлаго и горе, для результатов, одновременно хороших и плохих\nНичто, для результатов, которые и не хорошие и не плохие\nЗаклинание не принимает в расчёт обстоятельства, способные изменить исход, такие как накладывание дополнительных заклинаний или потерю или обретение спутников.\nЕсли вы накладываете это заклинание несколько раз до завершения продолжительного отдыха, существует накопительный шанс 25 процентов за каждое использование, начиная со второго, что вы получите случайный ответ. Мастер совершает этот бросок скрытно.",
    "url": "https://dnd.su/spells/40-augury/",
    "shortTime": "1 мин",
    "dmg": [],
    "mode": "none",
    "saveAbility": ""
