    "classesRu": [
      "друид",
      "следопыт"
    ],
    "desc": "Вы ненадолго сливаетесь с природой и получаете знание об окружающей территории. На открытом воздухе заклинание даёт вам знание о землях в пределах 3 миль. В пещерах и естественном подземном окружении радиус 300 футов. Заклинание не действует там, где природа заменена конструкциями, например, в городах и подвалах. Вы мгновенно получаете знание о трёх фактах на ваш выбор о следующих особенностях местности:\nМестность и водоёмы.\nПреобладающие растения, минералы, животные и разумные существа.\nМощные Исчадия, Небожители, Нежить, Феи или Элементали.\nВлияние с других планов существования.\nСтроения.\nНапример, вы можете определить местонахождение мощной Нежити, местонахождение чистой воды для питья и местонахождение окрестных поселений.",
