    "desc": "Пока заклинание активно, вы понимаете буквальный смысл всех услышанных речей на любых языках. Вы также понимаете письмена на любых языках, но вы должны касаться поверхности, на которой записаны слова. Требуется примерно 1 минута для чтения одной страницы текста.\nЭто заклинание не расшифровывает тайные послания в текстах и символы, такие как магические знаки, не являющиеся частью текста.",
