    "desc": "Из ваших рук вырывается волна холодного воздуха. Все существа в 60-футовом конусе должны совершить спасбросок Телосложения. Существа получают 8к8 урона холодом при провале или половину этого урона при успехе. Существа, убитые этим заклинанием, становятся замороженными статуями, пока не растают.\nНа больших уровнях. Если вы накладываете это заклинание, используя ячейку 6-го уровня или выше, урон увеличивается на 1к8 за каждый уровень ячейки выше пятого.",
