    "desc": "Вы зачерпываете теневую материю в Царстве Теней и создаёте в пределах дистанции неживой предмет из растительного вещества: ткань, верёвку, дерево, или что-то подобное. Этим заклинанием вы также можете создавать предметы из минералов, таких как камни, кристаллы и металлы. Создаваемый предмет должен помещаться в куб с длиной ребра 5 футов и должен иметь форму и материал, которые вы раньше видели.\nДлительность зависит от создаваемого материала. Если предмет составлен из нескольких материалов, используется самая короткая длительность.\nМатериал\nДлительность\nРастительное вещество\n1 день\nКамень или кристалл\n12 часов\nДрагоценные металлы\n1 час\nДрагоценные камни\n10 минут\nАдамантин или мифрил\n1 минута\nИспользование материала, созданного этим заклинанием, в качестве материального компонента для другого заклинания вызывает провал того заклинания.\nНа больших уровнях. Если вы накладываете это заклинание, используя ячейку 6-го уровня или выше, длина ребра куба увеличивается на 5 футов за каждый уровень ячейки выше пятого.",
