    "classesRu": [
      "друид"
    ],
    "desc": "Пошептавшись с духами природы, вы создаёте один из следующих эффектов в пределах дистанции:\nВы создаёте крохотный безвредный ощутимый эффект, предсказывающий погоду в текущем месте в течение следующих 24 часов. Это может быть золотистый шарик, означающий ясную погоду, облачко, означающее дождь, снежинка, и так далее. Эффект длится 1 раунд.\nВы мгновенно заставляете цветок распуститься, семечко прорасти, или почку раскрыться.\nВы создаёте мгновенный безвредный ощутимый эффект, такой как падающие листья, порыв ветра, звук маленького животного, или слабый запах скунса. Эффект должен находиться в кубе с длиной ребра 5 футов.\nВы мгновенно зажигаете или тушите свечу, факел или небольшой костёр.",
    "url": "https://dnd.su/spells/123-druidcraft/",
