    "desc": "Вы создаете три огненных луча и направляете их на цели, находящиеся в пределах дистанции. Это может быть одна цель или несколько.\nДля каждого луча совершите дальнобойную атаку заклинанием. При попадании цель получает 2к6 урона огнём.\nНа больших уровнях. Если вы накладываете это заклинание, используя ячейку 3-го уровня или выше, вы создаете один дополнительный луч за каждый уровень ячейки выше второго.",
