    "desc": "Вы можете видеть и слышать конкретное выбранное вами существо, находящееся на том же плане существования, что и вы. Цель должна совершить спасбросок Мудрости, модифицируемый тем, как хорошо вы знаете цель, и тем, какая связь с этим существом у вас есть. Если цель знает, что вы накладываете это заклинание, она может добровольно провалить спасбросок, если хочет, чтобы за ней следили.\nЗнание\nМодификатор\nспасброска\nЧерез посредников (вы только слышали о цели)\n+5\nИз первых рук (вы встречались с целью)\n+0\nЗнакомые (вы хорошо знаете цель)\n-5\nСвязь\nМодификатор\nспасброска\nОбраз или рисунок\n-2\nВещь или одежда\n-4\nЧасть тела, прядь волос, кусок ногтя и т.п.\n-10\nПри успехе цель не попадает под действие, и вы не можете использовать на ней это заклинание в течение 24 часов.\nПри провале заклинание создаёт невидимый сенсор в пределах 10 футов от цели. Вы можете видеть и слышать через него, как если бы вы там находились. Сенсор перемещается вместе с целью, оставаясь в пределах 10 футов от неё, пока активно заклинание. Существа, способные видеть невидимые предметы, видят сенсор как светящийся шарик размером с ваш кулак.\nВместо того чтобы нацеливаться на существо, вы можете выбрать целью место, уже виденное вами. В этом случае сенсор появляется в этом месте и не перемещается.",
