    "classes": [
      "cleric",
      "druid"
    ],
    "classesRu": [
      "друид",
      "жрец"
    ],
    "desc": "Вы касаетесь существа, мёртвого не больше двух сотен лет, умершего от чего угодно, кроме старости. Если душа цели свободна и согласна, цель возвращается к жизни с полными хитами.\nЭто заклинание закрывает все раны, нейтрализует все яды, исцеляет все болезни и снимает все проклятия, бывшие у существа в момент смерти. Заклинание заменяет повреждённые и отсутствующие органы и части тела. Если существо было Нежитью, оно возвращается к своему облику не-Нежити.\nЭто заклинание может даже воссоздать новое тело, если старого больше нет. В этом случае вы должны произнести вслух имя существа. Это существо появляется в свободном пространстве, выбранном вами в пределах 10 футов.\nЗаклинания, возвращающие к жизни: возрождение • оживление • реинкарнация • воскрешение • истинное воскрешение",
    "url": "https://dnd.su/spells/125-true-resurrection/",
    "shortTime": "1 час",
