    "desc": "Вы достигаете сознания одного существа, которое вы можете видеть, и заставляете его совершить спасбросок Интеллекта. Существо автоматически преуспевает, если оно имеет иммунитет к испугу. При провале цель теряет способность отличать друзей от врагов, относясь ко всем существам, которых она может видеть, как к врагам, пока заклинание активно. Каждый раз, когда цель получает урон, она может повторить спасбросок, окончив эффект на себе при успехе.\nКаждый раз, когда существо под действием заклинания выбирает другое существо в качестве цели, оно должно выбирать цель случайным образом среди существ, которых она может видеть в пределах досягаемости атаки, дистанции заклинания или других умений, которые она использует. Если враг провоцирует атаку от существа под действием заклинания, существо должно совершить эту атаку, если это возможно.",
