    "desc": "Ваша магия углубляет понимание существом собственного таланта. Вы касаетесь одного согласного существа и наделяете его специальными познаниями в одном навыке по вашему выбору. Пока заклинание активно, существо удваивает свой бонус мастерства для всех совершаемых им проверок характеристик, использующих выбранный навык.\nВы должны выбрать навык, которым существо уже владеет и который ещё не получает преимуществ от подобных эффектов, удваивающих его бонус мастерства, таких как «Компетентность».",
