    "desc": "Воздух начинает дрожать вокруг пяти существ по вашему выбору, которых вы можете видеть в пределах дистанции. Несогласное существо должно преуспеть в спасброске Мудрости, чтобы противостоять этому заклинанию. Вы телепортируете каждую затронутую цель в свободное пространство, которое вы можете видеть в пределах 120 футов от вас. Это пространство должно быть на земле или на полу.",
