    "id": null,
    "slug": "druid-grove",
    "name": "Роща друида [Druid Grove]",
    "nameEn": "Druid Grove",
    "level": 6,
    "school": "ограждение",
    "schoolEn": "",
    "time": "10 минут",
    "range": "Касание",
    "dur": "24 часа",
    "comp": [
      "v",
      "s",
      "m",
      "расходуемая заклинанием",
      "которая была собрана золотым серпом под светом полной луны)"
    ],
    "mat": "",
    "conc": false,
    "ritual": false,
    "classes": [
      "druid"
    ],
    "classesRu": [
      "друид"
    ],
    "desc": "Вы призываете духов природы для защиты области на открытом воздухе или под землёй. Эта область может быть кубом с длиной ребра от 30 до 90 футов. Здания и другие сооружения исключаются из этой области. Если вы накладываете это заклинание в одном и том же месте каждый день в течение года, заклинание длится до тех пор, пока не будет рассеяно.\nЗаклинание создает следующие эффекты в пределах области. Когда вы накладываете это заклинание, вы можете указать существ как друзей, которые будут невосприимчивы к эффектам заклинания. Вы также можете указать кодовое слово, которое, при произношении, делает говорящего невосприимчивым к этим эффектам.\nВся защищённая область источает магию. Рассеивание магии [Dispel magic], наложенное на область, при успехе удаляет только один из нижеследующих эффектов, а не всю область. Заклинатель выбирает, какой эффект окончить. Только когда все эффекты окончены, заклинание рассеивается.\nНепроглядный туман. Вы можете заполнить любое количество квадратов с длиной ребра 5 футов на земле густым туманом, делая их сильно заслонённой областью. Туман достигает 10 футов в высоту. Кроме того, каждый фут движения через туман стоит 2 дополнительных фута. Для существа, невосприимчивого к данному эффекту, туман ничего не скрывает и выглядит как лёгкая дымка с песчинками зеленого света, плавающими в воздухе.\nЦепкий подлесок. Вы можете заполнить любое количество квадратов с длиной ребра 5 футов на земле, которые не заполнены туманом, цепкими сорняками и лозой, как если бы они были созданы заклинанием опутывание [entangle]. Для существа, невосприимчивого к данному эффекту, сорняки и лоза ощущаются мягкими и меняют свою форму, чтобы служить временными сидениями или постелями.\nХранители рощи. Вы можете оживить до четырех деревьев в этой области, заставляя их выкорчевать себя из земли. Эти деревья имеют блок статистики пробуждённого дерева [awakened tree], за исключением того, что они не могут говорить, и их кора покрыта друидическими символами. Если любое существо, не иммунное к этому эффекту, заходит в защищаемую область, хранители рощи сражаются, пока не прогонят или не убьют вторженцев. Хранители рощи также подчиняются устным командам (действие не требуется), которые вы произносите в этой области. Если вы не даёте им команд, и в области нет незваных гостей, хранители рощи бездействуют. Хранители рощи не могут покинуть охраняемую область. Когда заклинание оканчивается, магия, оживляющая их, исчезает, и деревья снова укореняются, если это возможно.\nДополнительный эффект от заклинания. Вы можете выбрать один из следующих магических эффектов в защищенной области:\nПостоянный порыв ветра [gust of wind] в двух местах по вашему выбору\nШипы [spike growth] в одном месте по вашему выбору\nСтена ветров [wind wall] в двух местах по вашему выбору\nДля существа, невосприимчивого к данному эффекту, ветры – это приятный легкий бриз, а шипы безвредны.",
