    "desc": "Накладывая это заклинание, вы показываете драгоценный камень, используемый в качестве материального компонента, и выбираете любое количество существ в пределах дистанции, которые могут видеть вас. Каждая цель должна преуспеть в спасброске Мудрости, иначе станет очарованной вами до тех пор, пока заклинание не окончится, или пока вы или ваши спутники не причините вред очарованному существу. Будучи очарованным таким образом, существо не может делать ничего, кроме как использовать своё передвижение, чтобы безопасно приблизиться к вам. Существо, находящееся в пределах 5 футов от вас, не может двигаться, а просто жадно смотрит на драгоценный камень, который вы показываете.\nВ конце каждого своего хода поражённая цель может повторить спасбросок Мудрости. При успехе эффект на этой цели оканчивается.",
