    "classesRu": [
      "волшебник",
      "колдун",
      "чародей"
    ],
    "desc": "Накладывая заклинание, вы обращаетесь к магии Нижних или Верхних планов (по вашему выбору), чтобы преобразовать себя. Вы получаете следующие преимущества до тех пор, пока заклинание не окончится:\nВы имеете иммунитет к урону огнём и ядом (Нижние планы) или к урону излучением и некротической энергией (Верхние планы).\nВы имеете иммунитет к состоянию «отравленный» (Нижние планы) или к состоянию «очарованный» (Верхние планы).\nЗа вашей спиной появляются призрачные крылья, дарующие вам скорость полёта 40 футов.\nВы получаете бонус +2 к КД.\nВсе ваши атаки оружием считаются магическими, и, когда вы совершаете атаку оружием, вы можете использовать свой модификатор базовой характеристики вместо Силы или Ловкости для бросков атаки и урона.\nДействием Атака вы можете совершить две атаки вместо одной. Вы не получаете это преимущество, если у вас уже есть подобное умение (например «Дополнительная атака»), которое позволяет атаковать более одного раза за действие Атака.",
