    "desc": "Вы выпускаете мерцающее копьё психической силы из своего лба в существо, которое вы можете видеть в пределах дистанции. В качестве альтернативы вы можете произнести имя существа. Если названная цель находится в пределах дистанции, она становится целью заклинания, даже если вы её не видите. Если названная цель не находится в пределах дистанции, копьё исчезает без эффекта.\nЦель должна совершить спасбросок Интеллекта. При провале она получает 7к6 урона психической энергией и становится недееспособной до начала вашего следующего хода. При успехе она получает половину этого урона и остаётся дееспособной.\nНа больших уровнях. Если вы накладываете это заклинание, используя ячейку 5-го уровня или выше, урон увеличивается на 1к6 за каждый уровень ячейки выше 4-го.",
