    "classesRu": [
      "волшебник",
      "колдун"
    ],
    "desc": "Вы временно призываете трёх фамильяров — духов, которые принимают вид животных по вашему выбору. Каждый фамильяр следует правилам и опциям из заклинания поиск фамильяра [find familiar]. Все фамильяры, призванные этим заклинанием, должны быть одного выбранного вами вида (Исчадие, Небожитель или Фея). Если вы уже призвали фамильяра заклинанием поиск фамильяра или другим подобным заклинанием, то заклинание стая фамильяров призывает на одного фамильяра меньше.\nПризванные этим заклинанием фамильяры могут телепатически общаться с вами и делиться с вами видимой и слышимой информацией, пока они находятся в пределах 1 мили от вас.\nЕсли вы накладываете заклинание с дистанцией «касание», его может передать фамильяр по правилам заклинания поиск фамильяра. Однако вы можете передавать заклинание только через одного фамильяра за ход.\nНа больших уровнях. Если вы накладываете это заклинание, используя ячейку 3-го уровня или выше, вы вызываете дополнительного фамильяра за каждый уровень ячейки выше второго.",
